 parent,pp=cache[ex];pi=parent.set_index('id_link');cp={int(q.u):Point(q.geometry.coords[0]) for q in current.itertuples()}|{int(q.v):Point(q.geometry.coords[-1]) for q in current.itertuples()};newpoints=dict(cp);moved={v['node'] for item in items for v in item['moved_endpoints']};ids={v['child_link'] for v in items};attached=[]
