  xr,yr=next(iter(views.values()));fig.update_xaxes(range=xr,title_text='Local easting (km)',row=1,col=col);fig.update_yaxes(range=yr,scaleanchor='x' if col==1 else f'x{col}',scaleratio=1,row=1,col=col)
