 payload.append(dict(key=key,items=items,attachments=attached,views=views,view_labels=focuslabels,figure=json.loads(fig.to_json()),preview_checks=dict(connectivity_unchanged=True,shared_endpoints_consistent=True,positive_lengths=True,new_nonsimple_selected_lines=[v['child_link'] for v in attached if not v['is_simple']],cross_reach_intersections_checked=False,heads_refitted=False)))
