page='''<!doctype html><meta charset="utf-8"><title>21-case residual exterior geometry review</title><style>body{font:16px system-ui;margin:25px;color:#263744;line-height:1.5}p{max-width:1250px}select,button,textarea{font:inherit;padding:7px;margin:4px}table{border-collapse:collapse;font-size:14px}th,td{border:1px solid #ddd;padding:8px;vertical-align:top}textarea{width:95%;height:55px}.box{background:#f1f6f8;padding:15px}#plot{min-width:1100px}</style><h1>Additional review: residual exterior geometry in 21 cases</h1><p>This is a separate review of <b>34 exterior reach instances</b>, not a reopening of the 27 accepted fixes. The middle panel starts from the isolated candidate after those fixes. <b>37/unit 143 is excluded: your acceptance of its additional reversal and boundary flexibility remains recorded separately.</b></p><div class="box"><b>What you are deciding:</b> whether to restore each remaining exterior line to the reference geometry. For 32 reaches that also means returning a shared boundary coordinate to its original position and reconnecting selected-side endpoints. Two reaches only need a polyline change. The preview retains topology; it does not rerun the collapse or fit new heads.</div><p><b>Colours:</b> orange = exterior reach under review; purple = selected-side line that would be reattached; teal = other selected-region geometry; grey = exterior context. Gold = boundary node. Dotted lines and crosses show the alternative boundary position. Display lines are simplified at 1 m; measured lengths and stored geometry checks use the original lines.</p><p>Use the reach-specific close-ups and <b>Whole unit</b> before deciding. Inspect whether purple reattachments look reasonable or whether a local redesign is needed. The preview checks positive lengths, shared endpoints and unchanged connectivity, but does not establish absence of cross-reach intersections or hydraulic feasibility. No automatic claim is made that boundary movement was unnecessary.</p><button onclick="move(-1)">Previous</button><select id="pick" onchange="show()"></select><button onclick="move(1)">Next</button><span id="progress"></span><h2 id="title"></h2><div id="views"></div><div style="overflow-x:auto"><div id="plot"></div></div><h3>Reach-by-reach decisions</h3><p>“Accept restoration trial” approves isolated implementation and checks, not production publication. “Keep current geometry” explicitly accepts that exterior geometry exception. All entries start unreviewed.</p><div id="decisions"></div><button onclick="acceptCase()">Accept restoration trial for all reaches in this case</button><h3>Selected-side reattachments in the preview</h3><div id="attachments"></div><details><summary>Preview validation limits</summary><pre id="checks"></pre></details><p><button onclick="download()">Export residual-geometry decisions (21 cases)</button><span id="saved"></span></p><p>Earlier decisions are not modified by this export. Export before closing to preserve your review.</p><script>__PLOTLY__</script><script>const cases=__DATA__;const storage='river-residual-21-review-20261027';let reviews={};try{reviews=JSON.parse(localStorage.getItem(storage)||'{}')}catch(e){}const el=id=>document.getElementById(id);const pick=el('pick');cases.forEach((c,i)=>pick.add(new Option(c.key+' — '+c.items.length+' reach(es)',i)));const options=['Not reviewed','Accept restoration trial','Keep current geometry as exception','Needs local redesign — see notes','Defer — see notes'];function esc(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}function table(rows,cols){return '<table><tr>'+cols.map(k=>'<th>'+esc(k)+'</th>').join('')+'</tr>'+rows.map(r=>'<tr>'+cols.map(k=>'<td>'+esc(r[k])+'</td>').join('')+'</tr>').join('')+'</table>'}function focus(v){const r=cases[+pick.value].views[v];let u={};for(let i=1;i<=3;i++){const s=i===1?'':i;u['xaxis'+s+'.range']=r[0];u['yaxis'+s+'.range']=r[1]}Plotly.relayout('plot',u)}function show(){const c=cases[+pick.value];el('title').textContent=c.key;Plotly.react('plot',c.figure.data,c.figure.layout,{responsive:true,scrollZoom:true});el('views').replaceChildren();for(const v of Object.keys(c.views)){const b=document.createElement('button');b.textContent=c.view_labels[v];b.onclick=()=>focus(v);el('views').appendChild(b)}el('decisions').replaceChildren();for(const item of c.items){const box=document.createElement('div');box.className='box';const h=document.createElement('h4');h.textContent='Reference reach '+item.parent_link+' → current reach '+item.child_link;box.appendChild(h);const text=document.createElement('p');text.textContent=item.proposal+' Reference length '+item.reference_length_m.toFixed(3)+' m; current '+item.current_length_m.toFixed(3)+' m; difference '+item.length_delta_m.toFixed(3)+' m. '+(item.moved_endpoints.length?item.moved_endpoints.map(v=>'Node '+v.node+' moved '+v.displacement_m.toFixed(3)+' m.').join(' '):'Endpoint coordinates unchanged.');box.appendChild(text);const select=document.createElement('select');options.forEach(v=>select.add(new Option(v)));select.value=reviews[item.review_id]?.decision||'Not reviewed';const note=document.createElement('textarea');note.placeholder='Conditions or concerns for this reach';note.value=reviews[item.review_id]?.notes||'';const changed=()=>{reviews[item.review_id]={decision:select.value,notes:note.value};save()};select.onchange=changed;note.oninput=changed;box.appendChild(select);box.appendChild(note);el('decisions').appendChild(box)}el('attachments').innerHTML=table(c.attachments,['child_link','u','v','old_length_m','preview_length_m','length_delta_m','is_simple']);el('checks').textContent=JSON.stringify(c.preview_checks,null,2);progress()}function progress(){const items=cases.flatMap(c=>c.items);const n=items.filter(v=>reviews[v.review_id]&&reviews[v.review_id].decision!='Not reviewed').length;const k=cases.filter(c=>c.items.every(v=>reviews[v.review_id]&&reviews[v.review_id].decision!='Not reviewed')).length;el('progress').textContent=k+'/21 cases; '+n+'/34 reaches reviewed'}function save(){try{localStorage.setItem(storage,JSON.stringify(reviews));el('saved').textContent='Saved in this browser.'}catch(e){el('saved').textContent='Export to save decisions.'}progress()}function move(n){pick.value=Math.max(0,Math.min(cases.length-1,+pick.value+n));show()}function acceptCase(){for(const item of cases[+pick.value].items)reviews[item.review_id]={decision:'Accept restoration trial',notes:reviews[item.review_id]?.notes||''};save();show()}function download(){const data={review_type:'additional_residual_exterior_geometry',production_changes_authorized:false,prior_approvals_unchanged:true,unit143_reversal_accepted_separately:true,cases:cases.map(c=>({key:c.key,reaches:c.items.map(v=>({review_id:v.review_id,parent_link:v.parent_link,child_link:v.child_link,proposal:v.proposal,moved_endpoints:v.moved_endpoints,decision:reviews[v.review_id]?.decision||'Not reviewed',notes:reviews[v.review_id]?.notes||''}))}))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='residual-exterior-geometry-decisions.json';a.click();URL.revokeObjectURL(a.href)}show();</script>'''
(OUT/'review_21_cases.html').write_text(page.replace('__PLOTLY__',get_plotlyjs()).replace('__DATA__',json.dumps(payload,separators=(',',':')).replace('</','<\\/')))
